<div class="content-with-aside"><div class="stack"><section class="card"><div class="section-heading"><h2>Profil Perusahaan</h2><?= badge($perusahaan['statusVerifikasi']) ?></div><p class="prose"><?= nl2br(e($perusahaan['deskripsi'])) ?></p><dl class="summary-list two-up"><?php foreach(['alamat'=>'Alamat','emailPerusahaan'=>'Email Resmi','kontak'=>'Kontak','bidangUsaha'=>'Bidang Usaha'] as $k=>$label):?><div><dt><?= e($label) ?></dt><dd><?= e($perusahaan[$k]) ?></dd></div><?php endforeach;?></dl><?php if($perusahaan['website']):?><a target="_blank" rel="noopener noreferrer" href="<?= e($perusahaan['website']) ?>">Kunjungi website ↗</a><?php endif;?></section>
<section class="card"><h2>01 · Pemeriksaan Dokumen</h2><p class="muted">Buka berkas asli, lalu catat hasil pemeriksaan setiap dokumen.</p><?php if(!$dokumen):?><div class="alert info">Perusahaan belum mengunggah dokumen legalitas.</div><?php endif;?><?php foreach($dokumen as $d):?><div class="review-document"><div class="section-heading"><h3><?= e($d['namaDokumen']) ?></h3><?= badge($d['hasilPemeriksaan']) ?></div><p><a class="button secondary" target="_blank" rel="noopener" href="<?= e(url('dokumen/lihat',['id'=>$d['idDokumen']])) ?>"><?= icon('file') ?> Periksa PDF ↗</a></p><form method="post" action="<?= e(url('perusahaan/dokumen')) ?>"><?= csrf() ?><input type="hidden" name="idPerusahaan" value="<?= $perusahaan['idPerusahaan'] ?>"><input type="hidden" name="idDokumenPerusahaan" value="<?= $d['id'] ?>"><label>Hasil Pemeriksaan<select name="hasil" required><option value="">Pilih hasil</option><?php foreach(['Sesuai','Tidak sesuai','Bermasalah'] as $s):?><option<?= selected($d['hasilPemeriksaan'],$s) ?>><?= e($s) ?></option><?php endforeach;?></select></label><label>Catatan<textarea name="catatan" maxlength="2000" rows="2"><?= e($d['catatan']) ?></textarea></label><button class="button secondary">Simpan Pemeriksaan</button></form></div><?php endforeach;?></section>
<section class="card"><h2>Lowongan Perusahaan</h2><?php foreach($lowongan as $l):?><div class="list-row"><div><strong><?= e($l['namaLowongan']) ?></strong><small><?= e($l['jenisPekerjaan']) ?> · <?= e($l['lokasiPenempatan']) ?></small></div><?= badge($l['statusLowongan']) ?></div><?php endforeach;?><?php if(!$lowongan):?><p class="muted">Belum ada lowongan.</p><?php endif;?></section><section class="card"><h2>Riwayat Verifikasi</h2><?php foreach($riwayat as $h):?><article class="history-item"><div class="section-heading"><?= badge($h['hasil']) ?><small><?= tanggal($h['dibuatPada'],'d M Y, H:i') ?> WIB</small></div><p><?= e($h['catatan']) ?></p><small>Oleh <?= e($h['namaPengguna']) ?></small></article><?php endforeach;?><?php if(!$riwayat):?><p class="muted">Belum ada kesimpulan verifikasi.</p><?php endif;?></section></div>
<aside class="stack"><section class="card"><h2>02 · Kesimpulan Verifikasi</h2><form method="post" action="<?= e(url('perusahaan/verifikasi')) ?>"><?= csrf() ?><input type="hidden" name="idPerusahaan" value="<?= $perusahaan['idPerusahaan'] ?>"><label>Hasil Verifikasi<select name="hasil"><option>Layak</option><option>Perlu Perbaikan</option><option>Tidak Layak</option></select></label><label>Catatan Verifikasi<textarea name="catatan" rows="4" maxlength="3000" required placeholder="Tuliskan dasar hasil pemeriksaan."></textarea></label><button class="button secondary full">Simpan Kesimpulan</button></form></section><section class="card"><h2>03 · Keputusan Admin</h2><p class="muted">Persetujuan memerlukan seluruh dokumen Sesuai dan kesimpulan terakhir Layak.</p><form method="post" action="<?= e(url('perusahaan/keputusan')) ?>"><?= csrf() ?><input type="hidden" name="idPerusahaan" value="<?= $perusahaan['idPerusahaan'] ?>"><label>Alasan / Catatan<textarea name="alasan" maxlength="3000" rows="3" placeholder="Wajib diisi jika ditolak."></textarea></label><div class="stack"><button class="button full" name="keputusan" value="setujui"><?= icon('check') ?> Setujui Perusahaan</button><button class="button danger-outline full" name="keputusan" value="tolak">Tolak Perusahaan</button></div></form></section><details class="card danger-zone"><summary>Hapus karena pelanggaran</summary><p>Perusahaan dan lowongan disembunyikan. Akun rekruter dinonaktifkan; riwayat mahasiswa dipertahankan.</p><form method="post" action="<?= e(url('perusahaan/hapus')) ?>"><?= csrf() ?><input type="hidden" name="idPerusahaan" value="<?= $perusahaan['idPerusahaan'] ?>"><label>Alasan / Bukti Pelanggaran<textarea name="alasan" maxlength="3000" required rows="3"></textarea></label><button class="button danger full">Lanjutkan Penghapusan</button></form></details></aside></div>
